    """Return a new sorted copy of arr using bubble sort."""
    n = len(arr)
    # Sort the list
    for i in range(n):
        for j in range(0, n-i-1):
            # Swap if element found is greater than the next element
            if arr[j] > arr[j+1] :
                arr[j], arr[j+1] = arr[j+1], arr[j]
