    for i in range(len(arr) - 1):
        for j in range(len(arr) - 1):
            # Swap if element found is greater than the next element
            if arr[j] > arr[j + 1] :
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

